async function getJaguarsSchedule(season) {
  try {
    const state = await sf("/state/nfl");
    const currentWeek = state.display_week || state.week || 1;

    // Confirmed endpoint: /schedule/nfl/regular/{year} (no /v1/ prefix, no week)
    // Returns full season schedule as array of game objects
    const fullSchedule = await fetchWithFallback(
      `https://api.sleeper.app/schedule/nfl/regular/${season}`
    );

    if (!Array.isArray(fullSchedule)) {
      console.warn("[Jaguars] Schedule returned non-array:", typeof fullSchedule);
      return { game: null, week: currentWeek, state };
    }

    // Find JAX game in current week, then next week if not found
    let jaxGame = null;
    let targetWeek = currentWeek;
    for (const weekToTry of [currentWeek, currentWeek + 1]) {
      const weekGames = fullSchedule.filter(g => g.week === weekToTry);
      const found = weekGames.find(g =>
        g.home === JAX_TEAM_ID || g.away === JAX_TEAM_ID
      );
      if (found) { jaxGame = found; targetWeek = weekToTry; break; }
    }

    console.log("[Jaguars] Week", targetWeek, "game:", jaxGame);
    return { game: jaxGame, week: targetWeek, state };
  } catch(e) {
    console.warn("[Jaguars] Schedule fetch failed:", e.message);
    return { game: null, week: 1, state: null };
  }
}


