// ─── PICKS WINDOW UTILITIES ──────────────────────────────────────────────────
// Returns current time as a Date object in US Eastern time (auto EDT/EST)
function getNowEastern() {
  // Intl API gives us the correct UTC offset for Eastern including DST
  const now = new Date();
  const easternStr = now.toLocaleString("en-US", { timeZone: "America/New_York" });
  return new Date(easternStr);
}

// Returns true if picks are currently open
// Opens: Tuesday 3:00am Eastern
// Locks: Thursday 8:15pm Eastern
function isPicksWindowOpen() {
  const now = getNowEastern();
  const day = now.getDay();
  const hour = now.getHours();
  const minute = now.getMinutes();
  const timeVal = hour * 60 + minute;

  const OPEN_DAY = 2; const OPEN_TIME = 3 * 60;
  const LOCK_DAY = 4; const LOCK_TIME = 20 * 60 + 15;

  if (day === OPEN_DAY && timeVal >= OPEN_TIME) return true;
  if (day === 3) return true;
  if (day === LOCK_DAY && timeVal < LOCK_TIME) return true;
  return false;
}

// Returns true only AFTER Thursday 8:15pm lock (show checklist)
// Returns false if picks haven't opened yet (don't show checklist)
function isAfterDeadline() {
  const now = getNowEastern();
  const day = now.getDay();
  const hour = now.getHours();
  const minute = now.getMinutes();
  const timeVal = hour * 60 + minute;
  const LOCK_DAY = 4; const LOCK_TIME = 20 * 60 + 15;
  // After Thursday 8:15pm, or Friday, Saturday, Monday
  if (day === LOCK_DAY && timeVal >= LOCK_TIME) return true;
  if (day === 5 || day === 6 || day === 0 || day === 1) return true;
  return false;
}

// Returns a human-readable string of when picks open/close next
function getPicksWindowMessage() {
  const now = getNowEastern();
  const day = now.getDay();
  const hour = now.getHours();
  const minute = now.getMinutes();
  const timeVal = hour * 60 + minute;

  const OPEN_DAY = 2;
  const OPEN_TIME = 3 * 60;
  const LOCK_DAY = 4;
  const LOCK_TIME = 20 * 60 + 15;

  if (isPicksWindowOpen()) {
    // Show time until lock
    if (day === LOCK_DAY) {
      const minsLeft = LOCK_TIME - timeVal;
      const h = Math.floor(minsLeft / 60);
      const m = minsLeft % 60;
      return `🔒 Picks lock in ${h}h ${m}m (Thu 8:15pm ET)`;
    }
    return "🔒 Picks lock Thursday at 8:15pm ET";
  } else {
    // Show time until open
    const days = ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"];
    if (day === LOCK_DAY && timeVal >= LOCK_TIME) return "🔐 Picks are locked. Opens Tuesday at 3:00am ET.";
    if (day === 5) return "🔐 Picks are locked. Opens Tuesday at 3:00am ET.";
    if (day === 6) return "🔐 Picks are locked. Opens Tuesday at 3:00am ET.";
    if (day === 0) return "🔐 Picks are locked. Opens Tuesday at 3:00am ET.";
    if (day === 1) return "🔐 Picks are locked. Opens Tuesday at 3:00am ET.";
    if (day === OPEN_DAY && timeVal < OPEN_TIME) {
      const minsLeft = OPEN_TIME - timeVal;
      const h = Math.floor(minsLeft / 60);
      const m = minsLeft % 60;
      return `🔐 Picks open in ${h}h ${m}m (Tue 3:00am ET)`;
    }
    return "🔐 Picks are locked.";
  }
}

// ─── SEASON & SCHEDULE UTILITIES ─────────────────────────────────────────────

// After June 1: use current year's NFL schedule (released in May)
// Before June 1: use previous year's schedule
function getScheduleSeason() {
  const now = getNowEastern();
  const year = now.getFullYear();
  const month = now.getMonth() + 1; // 1-indexed
  return month >= 6 ? year : year - 1;
}

// Display year for "JaguarBros XXXX" — updates July 1 each year
function getLeagueDisplayYear() {
  const now = getNowEastern();
  const year = now.getFullYear();
  const month = now.getMonth() + 1;
  const day = now.getDate();
  // After July 1: show current year
  if (month > 7 || (month === 7 && day >= 1)) return year;
  return year - 1;
}

// Is it the offseason? (March 1 through first Tuesday of NFL season)
// NFL season typically starts second week of September
// We define offseason as March 1 through Tuesday before Week 1 kickoff
function isOffseason() {
  const now = getNowEastern();
  const month = now.getMonth() + 1;
  const day = now.getDay(); // 0=Sun
  // March 1 through end of August = offseason
  if (month >= 3 && month <= 8) return true;
  // September 1-7 before first Tuesday 3am = offseason  
  if (month === 9 && now.getDate() <= 7) return true;
  return false;
}


