function Rules() {
  const categories = ["League", "Playoffs", "Money", "Conduct", "Waivers & Trades", "Pick 'Em", "📄 Full Document"];
  const categoryIcons = { "League": "📋", "Playoffs": "🏆", "Money": "💰", "Conduct": "⚖️", "Waivers & Trades": "🔄", "Pick 'Em": "🎲", "📄 Full Document": "📄" };
  const categoryColors = { "League": T.teal, "Playoffs": T.gold, "Money": "#2e7d32", "Conduct": "#7b1fa2", "Waivers & Trades": "#1565c0", "Pick 'Em": "#c62828", "📄 Full Document": T.grayMid };
  const categoryGlows = { "League": T.tealGlow, "Playoffs": T.goldLight, "Money": "#66bb6a", "Conduct": "#ce93d8", "Waivers & Trades": "#64b5f6", "Pick 'Em": "#ef9a9a", "📄 Full Document": T.grayText };
  const [activeCategory, setActiveCategory] = useState("League");

  return (
    <div style={S.section}>
      <div style={S.sectionTitle}>📋 Official League Rules</div>

      {/* Category tabs */}
      <div style={{ display: "flex", gap: 6, marginBottom: 24, flexWrap: "wrap" }}>
        {categories.map(cat => (
          <button key={cat}
            style={{
              ...S.btn(activeCategory === cat),
              borderColor: activeCategory === cat ? categoryGlows[cat] : T.grayMid,
              color: activeCategory === cat ? categoryGlows[cat] : T.grayText,
              background: activeCategory === cat ? `${categoryColors[cat]}22` : "transparent",
            }}
            onClick={() => setActiveCategory(cat)}>
            {categoryIcons[cat]} {cat}
          </button>
        ))}
      </div>

      {/* Rules for selected category */}
      {(() => {
        const catRules = RULES.filter(r => r.category === activeCategory);
        const color = categoryColors[activeCategory];
        const glow = categoryGlows[activeCategory];

        if (activeCategory === "Money") {
          return (
            <div style={S.card}>
              {catRules.map((r, i) => (
                <div key={r.title} style={{
                  display: "flex", alignItems: "center", gap: 16,
                  padding: "14px 20px",
                  borderBottom: i < catRules.length - 1 ? `1px solid ${T.grayMid}` : "none",
                  background: i % 2 === 0 ? "#181818" : "transparent",
                }}>
                  <span style={{ fontSize: 24, flexShrink: 0 }}>{r.icon}</span>
                  <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 700, color: T.white, fontSize: 14 }}>{r.title}</div>
                    <div style={{ color: T.grayText, fontSize: 13, marginTop: 2, lineHeight: 1.4 }}>{r.detail}</div>
                  </div>
                  {["1st Place","2nd Place","3rd Place","Most Points Scored","Weekly Incentives","Buy-In"].includes(r.title) && (
                    <div style={{
                      fontWeight: 900, fontSize: 20,
                      color: r.title === "1st Place" ? T.goldLight : r.title === "2nd Place" ? "#A8A9AD" : r.title === "3rd Place" ? "#CD7F32" : r.title === "Buy-In" ? "#ff6666" : T.tealGlow,
                    }}>
                      {r.detail.startsWith("$") ? r.detail.split(" ")[0] : ""}
                    </div>
                  )}
                </div>
              ))}
            </div>
          );
        }

        return (
          <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {catRules.map(r => (
              <div key={r.title} style={{
                ...S.card, padding: "16px 20px",
                borderLeft: `4px solid ${color}`,
                display: "flex", gap: 14, alignItems: "flex-start",
              }}>
                <span style={{ fontSize: 26, flexShrink: 0, marginTop: 2 }}>{r.icon}</span>
                <div style={{ flex: 1 }}>
                  <div style={{ fontWeight: 700, color: glow, fontSize: 15, marginBottom: 6 }}>{r.title}</div>
                  <div style={{ color: T.grayText, fontSize: 13, lineHeight: 1.6 }}>{r.detail}</div>
                </div>
              </div>
            ))}
          </div>
        );
      })()}

      {/* Official document note - hidden on Full Document tab */}
      {activeCategory !== "📄 Full Document" && (
        <div style={{ marginTop: 24, background: `${T.teal}11`, border: `1px solid ${T.teal}33`, borderRadius: 8, padding: "12px 18px", fontSize: 12, color: T.grayText, lineHeight: 1.6 }}>
          📄 These rules reflect the JaguarBros Official League Rules document. All matters not explicitly covered are subject to Commissioner's Discretion (Article I).
        </div>
      )}

      {/* Full Document tab */}
      {activeCategory === "📄 Full Document" && (
        <div style={{ ...S.card, padding: "28px 32px" }}>
          <div style={{ fontWeight: 900, fontSize: 20, color: T.tealGlow, textAlign: "center", marginBottom: 28, letterSpacing: 2, textTransform: "uppercase" }}>
            JaguarBros Official League Rules
          </div>
          {[
            { n: "I", title: "Commissioner's Discretion", body: "All matters outside explicit guidelines are settled by Commissioner's Discretion with the intent of setting a standard for the league. Members may file formal complaints — majority vote (7/12) = successful appeal." },
            { n: "II", title: "League Format / Schedule", body: "17-week format. Regular season: 14 weeks. Schedule randomized each year. Platform: Sleeper.app. Standard scoring with decimals. K decimal scoring incorporated in 2020." },
            { n: "III", title: "Playoff Format", body: "6 teams qualify. 5 matchups over 3 weeks. Top 2 seeds receive first-round bye. Bracket adjusted so highest seed always plays lowest seed." },
            { n: "IV", title: "Payouts / Buy-In", body: "$75/team = $900 total pot. 1st: $500 · 2nd: $150 · 3rd: $50 · Most Points (16 wks): $50 · Weekly Incentives (15 × $10): $150." },
            { n: "V", title: "Weekly Incentives", body: "See the Weekly Incentives tab for all 15 weekly categories and current season winners." },
            { n: "VI", title: "Lineup Enforcement", body: "Full lineup required every week through Week 17, set before TNF kickoff. For Q/D players: notify @channel on Slack. Valid excuses considered if filed before the affected matchup." },
            { n: "VII", title: "Strike Rule", body: "2 strikes in 1 season = expulsion. Each strike = -10 Pick 'Em points. Strike Forgiveness: First strike may be erased by submitting a themed write-up (limit 1/season, Commissioner's Discretion)." },
            { n: "VIII", title: "Tiebreakers", body: "Weekly ties: decided by total bench points. Playoff seeding ties: head-to-head first. If split 1-1, highest season PF advances." },
            { n: "IX", title: "Weekly Sacko", body: "Lowest scorer each week receives -2 points from year-end Pick 'Em total." },
            { n: "X", title: "End of Season Sacko", body: "Worst overall record through all 17 weeks. Must complete the Wonderlic test before the following season's draft. Failure = expulsion." },
            { n: "XI", title: "Waiver Format", body: "Acquisition Budget system. $100 per team for the season. Waiver deadline: Week 12." },
            { n: "XII", title: "Trades", body: "Automatic 1-day processing via Sleeper. Commissioner does not push trades manually. All trades subject to investigation. Trade deadline: Week 12." },
            { n: "XIII", title: "Draft Date", body: "Goal: after 3rd preseason game. Subject to change based on league availability." },
            { n: "XIV", title: "Draft Order / Pick 'Em", body: "Picks due before TNF kickoff. Choose 6 matchup winners + Highest Score, Lowest Score, and Blowout each week through playoffs. Most correct picks = first draft choice. Players cannot select same Highest/Lowest score — first timestamp wins. Sabotage = -10 points." },
            { n: "XV", title: "Pick 'Em Bonus Opportunities", body: "Perfect Attendance (all picks all season): +10 pts. Weekly Perfection (11/11): +15 pts. League Contributor (write-up/video/meme): +5 pts, max 2/season." },
            { n: "XVI", title: "The Shamefoot Amendment", body: "Collusion = 1 strike + -10 Pick 'Em points. Includes financial transactions for advantages, intentional drops, or unbalanced trades." },
            { n: "XVII", title: "The F***ing Stu Amendment", body: "2 strikes in 1 season = expulsion. Patterns of nonparticipation across seasons may result in penalties larger than the standard -10." },
          ].map((a, i, arr) => (
            <div key={a.n} style={{ marginBottom: 20, paddingBottom: 20, borderBottom: i < arr.length - 1 ? `1px solid ${T.grayMid}` : "none" }}>
              <div style={{ fontWeight: 700, color: T.tealGlow, fontSize: 14, marginBottom: 6 }}>Article {a.n} — {a.title}</div>
              <div style={{ color: T.grayText, lineHeight: 1.7, fontSize: 13 }}>{a.body}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}


// ─── SETUP GUIDE TAB ─────────────────────────────────────────────────────────
function SetupGuide() {
  const steps = [
    { num: "01", title: "Create a Firebase Project", steps: ["Go to console.firebase.google.com and sign in with your Google account", 'Click "Add project" → name it "jaguarbros-fantasy" → Continue', "Disable Google Analytics (optional) → Create project"] },
    { num: "02", title: "Enable Realtime Database", steps: ['Click "Realtime Database" in the left sidebar', '"Create Database" → choose us-central1 → Enable', '"Start in test mode" (30 days open, then you secure it)'] },
    { num: "03", title: "Get Your Firebase Config", steps: ['Click ⚙️ → Project Settings', 'Scroll to "Your apps" → click </> to add a web app', 'Name it "jaguarbros-web" → Register app', "Copy the firebaseConfig object"] },
    { num: "04", title: "Paste Config into Site Code", steps: ["Open jaguarbros-fantasy.jsx in a text editor", "Find FIREBASE_CONFIG near the top (~line 10)", "Replace PASTE_YOUR_* values with your real config", "Save and reload — picks now save to Firebase!"] },
    { num: "05", title: "Verify Sleeper Auto-Import", steps: [`Site auto-fetches league from @${SLEEPER_USERNAME}`, "Uses previous_league_id to chain all seasons back to ${LEAGUE_START_YEAR}", "Scores, standings, and history update automatically — no manual edits needed"] },
  ];
  return (
    <div style={S.section}>
      <div style={S.sectionTitle}>🔧 Setup Guide</div>
      <div style={{ background: `${T.teal}18`, border: `1px solid ${T.teal}`, borderRadius: 8, padding: "12px 18px", marginBottom: 22, fontSize: 13, color: T.tealGlow }}>
        ✅ <strong>Sleeper is live</strong> — scores, standings, history pull automatically.<br />
        🔧 <strong>Firebase needs one-time setup</strong> (free, ~10 min) for pick submissions.
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 14 }}>
        {steps.map(s => (
          <div key={s.num} style={{ ...S.card, padding: "16px 20px" }}>
            <div style={{ display: "flex", gap: 14 }}>
              <div style={{ fontSize: 26, fontWeight: 900, color: T.teal, minWidth: 44, lineHeight: 1 }}>{s.num}</div>
              <div style={{ flex: 1 }}>
                <div style={{ fontWeight: 700, color: T.white, fontSize: 14, marginBottom: 8 }}>{s.title}</div>
                <ol style={{ margin: 0, paddingLeft: 18, display: "flex", flexDirection: "column", gap: 5 }}>
                  {s.steps.map((step, i) => <li key={i} style={{ color: T.grayText, fontSize: 12, lineHeight: 1.5 }}>{step}</li>)}
                </ol>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ─── APP ──────────────────────────────────────────────────────────────────────
const TABS = ["Standings", "Weekly Picks", "Pick Leaderboard", "Weekly Incentives", "Scoreboard", "Teams", "League History", "Archive", "Rules"];

export default function App() {
  const [tab, setTab] = useState("Standings");
  const [leagueData, setLeagueData] = useState(null);
  const [leagueError, setLeagueError] = useState(null);
  const [leagueLoading, setLeagueLoading] = useState(true);

  useEffect(() => {
    getLeagueData(SLEEPER_USERNAME, NFL_SEASON)
      .then(d => { setLeagueData(d); setLeagueLoading(false); })
      .catch(e => { setLeagueError(e.message); setLeagueLoading(false); });
  }, []);

  const leagueName = leagueData?.leagueInfo?.name || "JaguarBros Fantasy Football";
  const currentWeek = leagueData?.leagueInfo?.settings?.leg || "—";

  return (
    <div style={S.app}>
      <style>{`
        @keyframes spin{to{transform:rotate(360deg)}}
      `}</style>
      <nav style={S.nav}>
        <div style={S.navLogo}>
          <img src={LOGO_NAV} alt="JaguarBros" style={{ height: 44, width: "auto", borderRadius: 4, objectFit: "cover" }} />
          <div>
            <div style={S.navLogoText}>JaguarBros</div>
            <div style={S.navLogoSub}>Fantasy Football</div>
          </div>
        </div>
        <div style={S.navTabs}>
          {TABS.map(t => <button key={t} style={S.navBtn(tab === t)} onClick={() => setTab(t)}>{t}</button>)}
        </div>
      </nav>

      {tab === "Standings" && (
        <div style={S.hero}>
          <div style={S.heroGlow} />
          <div style={{ position: "relative" }}>
            <img src={LOGO_HERO} alt="JaguarBros Logo" style={{ height: 110, width: "auto", marginBottom: 12, borderRadius: 8, objectFit: "cover", boxShadow: "0 0 30px #00c8dc44" }} />
            <h1 style={S.heroTitle}>{leagueName}</h1>
            
            {!leagueLoading && !leagueError && (
              <div style={S.heroStats}>
                {[
                  [leagueData?.rosters?.length || 12, "Teams"],
                  [isOffseason() ? "Offseason" : `Week ${currentWeek}`, "Current Week"],
                  ["LIVE", "Sleeper Sync"],
                ].map(([num, label]) => (
                  <div key={label} style={{ textAlign: "center", minWidth: 100, display: "flex", flexDirection: "column", justifyContent: "flex-end" }}>
                    <span style={{ ...S.heroStatNum, fontSize: 24, lineHeight: 1.3, whiteSpace: "nowrap" }}>{num}</span>
                    <span style={S.heroStatLabel}>{label}</span>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      )}

      {leagueData?._stale && (
        <div style={{ background: "#1a1000", border: "1px solid #664400", padding: "10px 20px", fontSize: 12, color: "#ffaa44", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <span>⚠️ Showing cached data — Sleeper API unreachable. Scores may not be current.</span>
          <button style={{ ...S.btn(false), fontSize: 11, padding: "5px 12px" }} onClick={() => { setLeagueData(null); setLeagueLoading(true); getLeagueData(SLEEPER_USERNAME, NFL_SEASON).then(d => { setLeagueData(d); setLeagueLoading(false); }).catch(e => { setLeagueError(e.message); setLeagueLoading(false); }); }}>Retry</button>
        </div>
      )}
      {leagueError && (
        <div style={{ background: "#1a0000", border: "1px solid #660000", borderRadius: 0, padding: "12px 20px", color: "#ff6666", fontSize: 13, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
          <span>⚠️ Could not connect to Sleeper. Check that <strong>@{SLEEPER_USERNAME}</strong> has an active {NFL_SEASON} league.</span>
          <button style={{ ...S.btn(false), fontSize: 11, padding: "5px 12px", borderColor: "#660000", color: "#ff6666" }} onClick={() => { setLeagueError(null); setLeagueLoading(true); getLeagueData(SLEEPER_USERNAME, NFL_SEASON).then(d => { setLeagueData(d); setLeagueLoading(false); }).catch(e => { setLeagueError(e.message); setLeagueLoading(false); }); }}>Retry</button>
        </div>
      )}

      {tab === "Standings" && (
        <div style={{ maxWidth: 700, margin: "0 auto", padding: "20px 20px 0" }}>
          <JaguarsTile />
        </div>
      )}
      {tab === "Standings" && <Standings leagueData={leagueData} />}
      {tab === "Scoreboard" && <Scoreboard leagueData={leagueData} />}
      {tab === "Teams" && <Teams leagueData={leagueData} />}
      {tab === "League History" && <ErrorBoundary key="history"><LeagueHistory leagueData={leagueData} /></ErrorBoundary>}
      {tab === "Archive" && <ErrorBoundary key="archive"><Archive leagueData={leagueData} /></ErrorBoundary>}
      {tab === "Weekly Picks" && <WeeklyPicks leagueData={leagueData} />}
      {tab === "Pick Leaderboard" && <PickLeaderboard leagueData={leagueData} />}
      {tab === "Weekly Incentives" && <WeeklyIncentives leagueData={leagueData} />}
      {tab === "Rules" && <Rules />}
      {tab === "Setup Guide" && <SetupGuide />}

      <div style={{ borderTop: `2px solid ${T.teal}`, textAlign: "center", padding: "18px", color: T.grayText, fontSize: 11, letterSpacing: 2, textTransform: "uppercase", marginTop: 40, background: "#050505" }}>
        JaguarBros Fantasy Football · Est. {LEAGUE_START_YEAR} · Powered by Sleeper API
      </div>
    </div>
  );
}
      {/* ── Year-by-Year Final Standings ── */}
      <div style={{ marginBottom: 32 }}>
        <div style={{ fontWeight: 900, color: T.white, fontSize: 15, letterSpacing: 2, textTransform: "uppercase", marginBottom: 14 }}>
          Final Standings by Season
        </div>
        <div style={{ display: "flex", gap: 8, marginBottom: 18, flexWrap: "wrap" }}>
          {allSeasonSummaries.map(s => (
            <button key={s.year} style={{ ...S.btn(selectedYear === s.year), position: "relative" }} onClick={() => setSelectedYear(s.year)}>
              {s.year}
              {s.source === "espn" && <span style={{ fontSize: 8, color: T.gold, marginLeft: 4 }}>ESPN</span>}
              {s.status !== "complete" && s.source !== "espn" && <span style={{ fontSize: 8, color: T.tealGlow, marginLeft: 4 }}>LIVE</span>}
            </button>
          ))}
        </div>

        {selectedSeason && (
          <div style={S.card}>
            <div style={{ background: "linear-gradient(90deg,#001f26,#003840)", padding: "12px 18px", borderBottom: `2px solid ${T.teal}`, display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 8 }}>
              <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
                <span style={{ fontWeight: 900, color: T.tealGlow, letterSpacing: 2 }}>{selectedSeason.year} SEASON</span>
                {selectedSeason.source === "espn" && <span style={{ ...S.badge("gold") }}>ESPN ERA</span>}
                {selectedSeason.status !== "complete" && <span style={S.badge("teal")}>IN PROGRESS</span>}
              </div>
              <div style={{ display: "flex", gap: 16, flexWrap: "wrap" }}>
                {selectedSeason.champ && <span style={{ color: T.goldLight, fontSize: 12 }}>🏆 <strong>{selectedSeason.champ.owner}</strong></span>}
                {selectedSeason.sacko && <span style={{ color: "#ff6666", fontSize: 12 }}>💩 <strong>{selectedSeason.sacko.owner}</strong></span>}
                {!selectedSeason.sacko && <span style={{ color: T.grayText, fontSize: 12 }}>💩 Sacko: no record</span>}
              </div>
            </div>

            {selectedSeason.source === "espn" ? (
              <div style={{ padding: "24px 20px", textAlign: "center", color: T.grayText }}>
                <div style={{ fontSize: 28, marginBottom: 10 }}>📺</div>
                <div style={{ fontWeight: 700, color: T.white, marginBottom: 6 }}>ESPN Era — {selectedSeason.year}</div>
                <div style={{ fontSize: 13, marginBottom: 16 }}>Full standings data unavailable for ESPN seasons. Only champion and Sacko records were carried over.</div>
                <div style={{ display: "flex", justifyContent: "center", gap: 32 }}>
                  {selectedSeason.champ && (
                    <div style={{ textAlign: "center" }}>
                      <div style={{ fontSize: 32 }}>🏆</div>
                      <div style={{ fontWeight: 900, color: T.goldLight, fontSize: 16 }}>{selectedSeason.champ.owner}</div>
                      <div style={{ fontSize: 11, color: T.grayText, letterSpacing: 1 }}>CHAMPION</div>
                    </div>
                  )}
                  {selectedSeason.sacko && (
                    <div style={{ textAlign: "center" }}>
                      <div style={{ fontSize: 32 }}>💩</div>
                      <div style={{ fontWeight: 900, color: "#ff6666", fontSize: 16 }}>{selectedSeason.sacko.owner}</div>
                      <div style={{ fontSize: 11, color: T.grayText, letterSpacing: 1 }}>SACKO</div>
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <table style={S.table}>
                <thead><tr>
                  <th style={S.th}>Place</th><th style={S.th}>Team</th><th style={S.th}>Owner</th>
                  <th style={S.thR}>W</th><th style={S.thR}>L</th><th style={S.thR}>PTS</th><th style={S.thR}>Award</th>
                </tr></thead>
                <tbody>
                  {selectedSeason.standings.map((t, i) => {
                    const isChamp = selectedSeason.champ?.owner === t.owner && selectedSeason.status === "complete";
                    const isSacko = i === selectedSeason.standings.length - 1 && selectedSeason.status === "complete";
                    return (
                      <tr key={t.rosterId} style={{ background: i % 2 === 0 ? "#181818" : "transparent" }}>
                        <td style={S.td}><span style={S.rankBadge(i)}>{i + 1}</span></td>
                        <td style={S.td}><span style={{ fontWeight: 700, color: isChamp ? T.goldLight : isSacko ? "#ff6666" : T.white }}>{t.team}</span></td>
                        <td style={{ ...S.td, color: T.grayText }}>{t.owner}</td>
                        <td style={{ ...S.tdR, color: T.goldLight, fontWeight: 700 }}>{t.wins}</td>
                        <td style={{ ...S.tdR, color: T.grayText }}>{t.losses}</td>
                        <td style={S.tdR}>{t.pts.toFixed(2)}</td>
                        <td style={S.tdR}>
                          {isChamp && <span style={S.badge("gold")}>🏆 CHAMP</span>}
                          {isSacko && <span style={S.badge("red")}>💩 SACKO</span>}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            )}
          </div>
        )}
      </div>


